// Track layouts drawn from OpenStreetMap race-track lines. Generated by
// data/import/build-track-outlines.ts; don't edit the JSON by hand. Only
// imported by server components, so the file never ships to the browser.
import outlines from "./track-outlines.json";

export interface TrackOutline {
  /** SVG path data in a viewBox of 0 0 w h (the longer side is 1000). */
  d: string;
  w: number;
  h: number;
  /** Total length of the drawn lines, metres (includes pit lanes). */
  lengthM: number;
}

const TRACK_OUTLINES = outlines as Record<string, TrackOutline>;

export function trackOutline(slug: string): TrackOutline | undefined {
  return TRACK_OUTLINES[slug];
}
